(()=>{'use strict';const conf=window.EXPLORER,$=id=>document.getElementById(id),ids=['angle','force','length','direction'];let running=false,frame=null,start=0;const key='cg-explorer-'+conf.id;function position(x,y){return `${x.toFixed(3)} ${y.toFixed(3)}`;}function draw(){const angle=+$('angle').value,force=+$('force').value,length=+$('length').value,direction=+$('direction').value;const a=angle*Math.PI/180,d=direction*Math.PI/180;const scale=220,r=length*scale,x=180+r*Math.cos(a),y=200-r*Math.sin(a),ux=Math.cos(d),uy=-Math.sin(d);const along=(180-x)*ux+(200-y)*uy,px=x+along*ux,py=y+along*uy;const arm=length*Math.abs(Math.sin(d-a));$('lever').setAttribute('d',`M180 200L${position(x,y)}`);$('end').setAttribute('cx',x);$('end').setAttribute('cy',y);$('forceLine').setAttribute('d',`M${position(x-ux*600,y-uy*600)}L${position(x+ux*600,y+uy*600)}`);$('armLine').setAttribute('d',`M180 200L${position(px,py)}`);const arrow=force/1000*95;$('forceArrow').setAttribute('d',`M${position(x,y)}L${position(x+ux*arrow,y+uy*arrow)}`);$('forceArrow').style.display=force===0?'none':'';$('arm').textContent=arm.toFixed(3)+' m';$('moment').textContent=(force*arm).toFixed(1)+' N·m';ids.forEach(id=>{$(id+'Out').textContent=$(id).value+' '+$(id).dataset.unit;});}
function stop(){running=false;cancelAnimationFrame(frame);$('play').textContent=conf.play;$('play').setAttribute('aria-pressed','false');}function tick(now){if(!running)return;$('angle').value=Math.round(60*Math.sin((now-start)/1800));draw();frame=requestAnimationFrame(tick);}ids.forEach(id=>$(id).addEventListener('input',()=>{stop();draw();}));$('play').setAttribute('aria-pressed','false');$('play').addEventListener('click',()=>{if(running)return stop();running=true;start=performance.now();$('play').textContent=conf.pause;$('play').setAttribute('aria-pressed','true');frame=requestAnimationFrame(tick);});$('reset').addEventListener('click',()=>{stop();ids.forEach((id,i)=>{$(id).value=[30,100,.4,-90][i];});draw();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});try{const state=JSON.parse(sessionStorage.getItem(key));if(state)ids.forEach(id=>{const v=state[id];if(Number.isFinite(v)&&v>=+$(id).min&&v<=+$(id).max)$(id).value=v;});}catch{}window.addEventListener('pagehide',()=>{try{sessionStorage.setItem(key,JSON.stringify(Object.fromEntries(ids.map(id=>[id,+$(id).value]))));}catch{}});draw();})();
